manifest.content:
{
  "name": "sdl2",
  "version": "2.32.8",
  "description": "Simple DirectMedia Layer is a cross-platform development library designed to provide low level access to audio, keyboard, mouse, joystick, and graphics hardware via OpenGL and Direct3D.",
  "homepage": "https://www.libsdl.org/download-2.0.php",
  "license": "Zlib",
  "dependencies": [
    {
      "name": "vcpkg-cmake",
      "host": true
    },
    {
      "name": "vcpkg-cmake-config",
      "host": true
    }
  ],
  "default-features": [
    {
      "name": "dbus",
      "platform": "linux"
    },
    {
      "name": "ibus",
      "platform": "linux"
    },
    {
      "name": "wayland",
      "platform": "linux"
    },
    {
      "name": "x11",
      "platform": "linux"
    }
  ],
  "features": {
    "alsa": {
      "description": "Support for alsa audio",
      "dependencies": [
        "alsa"
      ]
    },
    "dbus": {
      "description": "Build with D-Bus support",
      "dependencies": [
        {
          "name": "dbus",
          "default-features": false,
          "platform": "linux"
        }
      ]
    },
    "ibus": {
      "description": "Build with ibus IME support",
      "supports": "linux"
    },
    "samplerate": {
      "description": "Use libsamplerate for audio rate conversion",
      "dependencies": [
        "libsamplerate"
      ]
    },
    "vulkan": {
      "description": "Vulkan functionality for SDL"
    },
    "wayland": {
      "description": "Build with Wayland support",
      "supports": "linux"
    },
    "x11": {
      "description": "Build with X11 support",
      "supports": "!windows"
    }
  }
}

{
  "name": "tinyxml2",
  "version-semver": "11.0.0",
  "description": "A simple, small, efficient, C++ XML parser",
  "homepage": "https://github.com/leethomason/tinyxml2",
  "license": "Zlib",
  "dependencies": [
    {
      "name": "vcpkg-cmake",
      "host": true
    },
    {
      "name": "vcpkg-cmake-config",
      "host": true
    }
  ]
}

{
  "name": "mpg123",
  "version": "1.32.9",
  "port-version": 1,
  "description": "mpg123 is a real time MPEG 1.0/2.0/2.5 audio player/decoder for layers 1, 2 and 3 (MPEG 1.0 layer 3 also known as MP3).",
  "homepage": "https://sourceforge.net/projects/mpg123/",
  "license": "LGPL-2.1-or-later",
  "supports": "!xbox",
  "dependencies": [
    {
      "name": "vcpkg-cmake",
      "host": true
    },
    {
      "name": "vcpkg-cmake-config",
      "host": true
    },
    {
      "name": "yasm",
      "host": true,
      "features": [
        "tools"
      ],
      "platform": "windows & !mingw"
    }
  ]
}

{
  "name": "angle",
  "version-string": "chromium_7258",
  "port-version": 1,
  "description": [
    "A conformant OpenGL ES implementation for Windows, Mac and Linux.",
    "The goal of ANGLE is to allow users of multiple operating systems to seamlessly run WebGL and other OpenGL ES content by translating OpenGL ES API calls to one of the hardware-supported APIs available for that platform. ANGLE currently provides translation from OpenGL ES 2.0 and 3.0 to desktop OpenGL, OpenGL ES, Direct3D 9, and Direct3D 11. Support for translation from OpenGL ES to Vulkan is underway, and future plans include compute shader support (ES 3.1) and MacOS support."
  ],
  "homepage": "https://github.com/google/angle",
  "license": "BSD-3-Clause",
  "dependencies": [
    "egl-registry",
    "opengl-registry",
    {
      "name": "vcpkg-cmake",
      "host": true
    },
    {
      "name": "vcpkg-cmake-config",
      "host": true
    },
    {
      "name": "vcpkg-get-python-packages",
      "host": true
    },
    "zlib"
  ],
  "features": {
    "metal": {
      "description": "Metal support for angle",
      "supports": "osx | ios"
    }
  }
}
